// Analista SPI Vivo DEV — inteligência determinística sobre resultados calculados pelos Cores.
let analystMode='situacao',analystPrev=null,analystHistory=[];
function analystMunicipios(){
  const m=new Map();
  const get=n=>{const k=norm(n);if(!k)return null;if(!m.has(k))m.set(k,{nome:n||k,score:0,sinais:[],sites4h:0});return m.get(k)};
  weatherEvents.forEach(e=>{const x=get(e.municipio);if(!x)return;const ativo=e.ameaca_ativa||e.tempestade,alto=['CRITICO','ALTO'].includes(norm(e.nivel_risco));if(ativo){x.score+=4;x.sinais.push('clima')};if(alto){x.score+=5;x.sinais.push(norm(e.nivel_risco))};const r=Number(e.rajada_kmh||0);if(r>=60){x.score+=4;x.sinais.push(`rajada ${r} km/h`)}else if(r>=45){x.score+=2;x.sinais.push(`rajada ${r} km/h`)};const ch=Number(e.chuva_total_mm||0);if(ch>=20){x.score+=4;x.sinais.push(`chuva ${ch} mm`)}else if(ch>=10){x.score+=2;x.sinais.push(`chuva ${ch} mm`)}});
  defesaEvents.forEach(e=>{const x=get(e.municipio);if(x){x.score+=4;x.sinais.push('Defesa Civil')}});
  energyEvents.forEach(e=>{const x=get(e.municipio);if(x){x.score+=3;x.sinais.push('energia')}});
  fireEvents.forEach(e=>{const x=get(e.municipio);if(x){x.score+=norm(e.classificacao)==='URGENTE'?7:3;x.sinais.push(`Fire ${e.classificacao||''}`.trim())}});
  siteEvents.filter(siteIsCritical).forEach(e=>{const x=get(e.municipio);if(x){x.sites4h+=1;x.score+=1}});
  return [...m.values()].sort((a,b)=>b.score-a.score||b.sites4h-a.sites4h||a.nome.localeCompare(b.nome,'pt-BR'));
}
function analystSnapshot(){const threats=weatherEvents.filter(e=>e.ameaca_ativa||e.tempestade),critical=weatherEvents.filter(e=>['CRITICO','ALTO'].includes(norm(e.nivel_risco))),vulnerable=weatherEvents.filter(e=>Number(e.sites_ate_4h||0)>0),maxGust=[...weatherEvents].sort((a,b)=>Number(b.rajada_kmh||0)-Number(a.rajada_kmh||0))[0],maxRain=[...weatherEvents].sort((a,b)=>Number(b.chuva_total_mm||0)-Number(a.chuva_total_mm||0))[0],fireUrg=fireEvents.filter(e=>norm(e.classificacao)==='URGENTE'),dc=new Set(defesaEvents.map(e=>norm(e.municipio)).filter(Boolean)),convergence=weatherEvents.filter(w=>dc.has(norm(w.municipio))&&(w.ameaca_ativa||w.tempestade)),critSites=siteEvents.filter(siteIsCritical),affected=new Set([...threats.map(e=>norm(e.municipio)),...defesaEvents.map(e=>norm(e.municipio)),...energyEvents.map(e=>norm(e.municipio)),...fireEvents.map(e=>norm(e.municipio))].filter(Boolean)),exposedCritSites=critSites.filter(e=>affected.has(norm(e.municipio))),municipios=analystMunicipios();let score=threats.length*4+critical.length*6+fireUrg.length*7+fireEvents.length*2+convergence.length*5+Math.min(energyEvents.length,20)+Math.min(exposedCritSites.length,20),readiness='PREPARADA';if(critical.length||fireUrg.length||threats.length>=5)readiness='CRÍTICA';else if(threats.length||fireEvents.length||defesaEvents.length||energyEvents.length)readiness='ATENÇÃO';return{threats,critical,vulnerable,maxGust,maxRain,fireUrg,convergence,critSites,exposedCritSites,municipios,readiness,score}}
function analystTrend(s){if(!analystPrev)return{label:'● AO VIVO',level:'stable',change:'Linha de base operacional estabelecida. O painel agora reage às atualizações dos Cores.'};const d=s.score-analystPrev.score;if(d>=5)return{label:'↑ RISCO AUMENTANDO',level:'up',change:`⚠️ Mudança detectada: pressão operacional aumentou (+${d} pontos).`};if(d<=-5)return{label:'↓ RISCO REDUZINDO',level:'down',change:`✅ Mudança detectada: pressão operacional reduziu (${d} pontos).`};return{label:'→ SEM MUDANÇA MATERIAL',level:'stable',change:'🔎 As fontes atualizaram, mas não houve alteração material do quadro operacional.'}}
function analystTop(s,n=3){return s.municipios.filter(x=>x.score>0).slice(0,n)}
function analystText(mode='situacao',question=''){const s=analystSnapshot(),gust=s.maxGust?`${s.maxGust.municipio}: ${s.maxGust.rajada_kmh} km/h`:'sem dado',rain=s.maxRain?`${s.maxRain.municipio}: ${s.maxRain.chuva_total_mm} mm`:'sem dado',top=analystTop(s),lines=[];const topTxt=top.length?top.map((x,i)=>`${i+1}. <b>${esc(x.nome)}</b> — ${[...new Set(x.sinais)].slice(0,3).map(esc).join(' + ')}${x.sites4h?` • ${x.sites4h} site(s) ≤4h`:''}`).join('<br>'):'Nenhum município com sinal operacional relevante neste ciclo.';
if(mode==='preparacao'){lines.push(`<b>🎯 Preparação da Regional — ${s.readiness}</b>`);lines.push(`<b>Onde agir primeiro</b><br>${topTxt}`);lines.push(`Hoje o painel cruza ${s.threats.length} ameaça(s) climática(s), ${s.convergence.length} convergência(s) clima + Defesa Civil e ${s.exposedCritSites.length} site(s) ≤4h em municípios presentes nas camadas de risco/impacto.`);if(top.length)lines.push(`📌 <b>Ação recomendada agora:</b> validar GMGs, autonomia real, equipes, acesso e escalonamento começando por ${esc(top[0].nome)}${top[1]?` e ${esc(top[1].nome)}`:''}.`);else lines.push('📌 <b>Ação recomendada agora:</b> manter prontidão e acompanhar mudanças dos Cores.');if(s.convergence.length)lines.push(`🚨 Há convergência clima + Defesa Civil em ${s.convergence.length} município(s), elevando a prioridade de acompanhamento.`)}else if(mode==='projecao'){lines.push('<b>🛰️ Projeção operacional</b>');lines.push(`Maior rajada disponível: ${esc(gust)}. Maior chuva total disponível: ${esc(rain)}.`);if(top.length)lines.push(`<b>Corredor de atenção atual</b><br>${topTxt}`);lines.push('Origem, trajetória, chegada, pico e saída só serão apresentados quando vierem de cálculo/fonte meteorológica estruturada. O Analista não inventa deslocamento.')}else{lines.push(`<b>📡 SPI agora — ${s.readiness}</b>`);lines.push(`Clima ${s.threats.length} ameaça(s) • Energia ${energyEvents.length} região(ões) • Fire ${fireEvents.length} • Defesa Civil ${defesaEvents.length} município(s) • ${s.exposedCritSites.length} site(s) ≤4h expostos.`);lines.push(`<b>Prioridades neste instante</b><br>${topTxt}`);lines.push(`Picos disponíveis: rajada ${esc(gust)}; chuva ${esc(rain)}.`);if(s.critical.length)lines.push(`⚠️ ${s.critical.length} município(s) estão em nível ALTO/CRÍTICO no Weather Risk.`)}
if(question){const q=norm(question);if(q.includes('ONDE')||q.includes('ATENCAO')||q.includes('PRIOR'))lines.push(`<b>Resposta:</b><br>${topTxt}`);else if(q.includes('QUEIM')||q.includes('FOGO'))lines.push(`<b>Resposta:</b> ${fireEvents.length} evento(s) Fire ativo(s).`);else if(q.includes('ENERG'))lines.push(`<b>Resposta:</b> ${energyEvents.length} região(ões) na camada Energia.`);else if(q.includes('DEFESA'))lines.push(`<b>Resposta:</b> ${defesaEvents.length} município(s) na Defesa Civil.`);else if(q.includes('SITE')||q.includes('AUTON'))lines.push(`<b>Resposta:</b> ${s.critSites.length} sites ≤4h na base; ${s.exposedCritSites.length} em municípios presentes nas camadas operacionais atuais.`);else if(q.includes('CHUVA'))lines.push(`<b>Resposta:</b> maior chuva disponível: ${esc(rain)}.`);else if(q.includes('VENTO')||q.includes('RAJADA'))lines.push(`<b>Resposta:</b> maior rajada disponível: ${esc(gust)}.`);else lines.push(`<b>Resposta operacional:</b> quadro ${s.readiness}. Prioridade atual: ${top.length?esc(top[0].nome):'sem município prioritário'}.`)}return lines.join('<br><br>')}
function setAnalystActive(mode){document.querySelectorAll('[data-analysis]').forEach(b=>{const a=b.dataset.analysis===mode;b.classList.toggle('active',a);b.setAttribute('aria-pressed',a?'true':'false')})}
function refreshAnalyst(){const p=document.getElementById('analystPanel');if(!p)return;const s=analystSnapshot(),t=analystTrend(s),badge=document.getElementById('readinessBadge');badge.textContent=s.readiness;badge.dataset.level=norm(s.readiness);document.getElementById('analystSummary').innerHTML=analystText(analystMode);document.getElementById('analystUpdated').textContent=`Fire ${fireEvents.length} • Clima ${weatherEvents.length} • Energia ${energyEvents.length} • Defesa ${defesaEvents.length} • Sites ${siteEvents.length}`;const tr=document.getElementById('analystTrend');tr.textContent=t.label;tr.dataset.level=t.level;document.getElementById('analystChange').textContent=t.change;document.getElementById('analystClock').textContent=`Analisado ${new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`;const top=analystTop(s,2);document.getElementById('analystWatch').textContent=`${s.threats.length} ameaça(s) clima • ${s.convergence.length} convergência(s) Defesa • ${s.exposedCritSites.length} sites ≤4h expostos${top.length?` • foco: ${top.map(x=>x.nome).join(' / ')}`:''}`;if(!analystPrev||t.level!=='stable'){analystHistory.unshift(`${new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} — ${t.label}`);analystHistory=analystHistory.slice(0,4)}document.getElementById('analystTimeline').innerHTML='<b>🕒 Linha do tempo desta sessão</b>'+analystHistory.map(x=>`<div>${esc(x)}</div>`).join('');analystPrev=s;setAnalystActive(analystMode)}
function analystRun(mode){analystMode=mode||'situacao';refreshAnalyst();const x=document.getElementById('analystSummary');x.classList.remove('analyst-flash');void x.offsetWidth;x.classList.add('analyst-flash')}
function analystAsk(){const q=document.getElementById('analystQuestion').value.trim(),a=document.getElementById('analystAnswer');a.innerHTML=q?analystText('situacao',q):'<b>Digite uma pergunta para o Analista SPI.</b>';a.classList.remove('analyst-flash');void a.offsetWidth;a.classList.add('analyst-flash')}
document.querySelectorAll('[data-analysis]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();analystRun(b.dataset.analysis)}));document.getElementById('analystAsk')?.addEventListener('click',e=>{e.preventDefault();analystAsk()});document.getElementById('analystQuestion')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();analystAsk()}});setAnalystActive(analystMode);setInterval(refreshAnalyst,10000);setTimeout(refreshAnalyst,1200);

