// Visão de Comando DEV: mesma inteligência, menor carga visual.
function commandForecastCandidates(){const now=Date.now(),out=[];(forecastSpi.regioes||[]).forEach(r=>{const rows=(r.previsao_horaria||[]).filter(x=>{const t=new Date(x.data_hora).getTime();return Number.isFinite(t)&&t>=now-10*60*1000&&t<=now+12*3600000});if(!rows.length)return;const worst=[...rows].sort((a,b)=>Number(b.rajada_kmh||0)-Number(a.rajada_kmh||0)||Number(b.probabilidade_chuva||0)-Number(a.probabilidade_chuva||0))[0];if(Number(worst.rajada_kmh||0)>=45||Number(worst.probabilidade_chuva||0)>=70||[95,96,99].includes(Number(worst.weather_code))){out.push({regiao:r.regiao,hora:worst.data_hora,rajada:worst.rajada_kmh,chuva:worst.precipitacao_mm,prob:worst.probabilidade_chuva,tempestade:[95,96,99].includes(Number(worst.weather_code))})}});return out.sort((a,b)=>Number(b.tempestade)-Number(a.tempestade)||Number(b.rajada)-Number(a.rajada)).slice(0,5)}
function renderCommandView(){const root=document.getElementById('commandView');if(!root)return;const snap=analystSnapshot(),top=analystTop(snap,5),ready=document.getElementById('commandReadiness');ready.textContent=snap.readiness;ready.dataset.level=norm(snap.readiness);const imp=[...importantOfficialEvents(),...importantForecastEvents()].sort((a,b)=>b.score-a.score)[0];document.getElementById('commandUrgentText').innerHTML=imp?importantMessage(imp):'<strong>Nenhum evento urgente consolidado neste ciclo.</strong> Operação em monitoramento preventivo.';document.getElementById('commandPriorityList').innerHTML=top.length?top.map((x,i)=>`<button class="command-rank" data-command-city="${esc(x.nome)}"><strong>${i+1}</strong><span><b>${esc(x.nome)}</b><small>${[...new Set(x.sinais)].slice(0,3).map(esc).join(' • ')||'sinal operacional'}${x.sites4h?` • ${x.sites4h} site(s) ≤4h`:''}</small></span><i>→</i></button>`).join(''):'<div class="command-empty">Nenhuma região exige priorização neste ciclo.</div>';document.querySelectorAll('[data-command-city]').forEach(b=>b.onclick=()=>{showMapTab();focusMunicipio(b.dataset.commandCity)});const fc=commandForecastCandidates();document.getElementById('commandNextHours').innerHTML=fc.length?fc.map(x=>`<div class="command-row"><b>${esc(x.regiao)}</b><span>${new Date(x.hora).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} • ${x.tempestade?'⛈️ tempestade • ':''}🌬️ ${esc(x.rajada??'—')} km/h • 🌧️ ${esc(x.chuva??'—')} mm (${esc(x.prob??'—')}%)</span></div>`).join(''):'<div class="command-empty">Sem sinal meteorológico relevante nas próximas 12h dos polos publicados.</div>';document.getElementById('commandVulnerability').innerHTML=`<div class="command-kpis"><div><strong>${snap.vulnerable.reduce((n,x)=>n+Number(x.sites_ate_4h||0),0)}</strong><span>sites ≤4h sob ameaça clima</span></div><div><strong>${snap.exposedCritSites.length}</strong><span>sites críticos expostos</span></div><div><strong>${snap.convergence.length}</strong><span>convergências Clima + Defesa</span></div><div><strong>${snap.fireUrg.length}</strong><span>Fire urgente</span></div></div>`;document.getElementById('commandWatch').innerHTML=`<div class="command-row"><b>🌩️ Clima</b><span>${snap.threats.length} ameaça(s) ativa(s)</span></div><div class="command-row"><b>🚨 Defesa Civil</b><span>${defesaEvents.length} alerta(s)</span></div><div class="command-row"><b>⚡ Energia</b><span>${energyEvents.length} ocorrência(s)</span></div><div class="command-row"><b>🔥 Fire</b><span>${fireEvents.length} evento(s)</span></div><div class="command-row"><b>📡 Sites</b><span>${siteEvents.length} carregados</span></div>`}
function focusMunicipio(nome){const n=norm(nome),w=weatherEvents.find(x=>norm(x.municipio)===n),d=defesaEvents.find(x=>norm(x.municipio)===n),e=energyEvents.find(x=>norm(x.municipio)===n),f=fireEvents.find(x=>norm(x.municipio)===n),x=w||d||e||f;if(x&&Number.isFinite(Number(x.latitude))&&Number.isFinite(Number(x.longitude)))map.flyTo([Number(x.latitude),Number(x.longitude)],10,{duration:.7})}
