let fireViewSavedToggles=null;
function fireViewSaveToggles(){if(fireViewSavedToggles)return;fireViewSavedToggles={fire:document.getElementById('fireToggle')?.checked!==false,weather:document.getElementById('weatherToggle')?.checked!==false,energy:document.getElementById('energyToggle')?.checked!==false,defesa:document.getElementById('defesaToggle')?.checked!==false,sites:document.getElementById('sitesToggle')?.checked===true}}
function fireViewApplyLayers(){const set=(id,v)=>{const e=document.getElementById(id);if(e)e.checked=v};set('fireToggle',true);set('weatherToggle',false);set('energyToggle',false);set('defesaToggle',false);set('sitesToggle',false);renderFire();renderWeather();renderEnergy();renderDefesa();renderSites()}
