let mobileViewSavedToggles=null,mobileBackboneWasVisible=false;
function mobileViewSaveState(){if(mobileViewSavedToggles)return;mobileViewSavedToggles={fire:document.getElementById('fireToggle')?.checked!==false,weather:document.getElementById('weatherToggle')?.checked!==false,energy:document.getElementById('energyToggle')?.checked!==false,defesa:document.getElementById('defesaToggle')?.checked!==false,sites:document.getElementById('sitesToggle')?.checked===true};mobileBackboneWasVisible=Boolean(layer&&map.hasLayer(layer))}
