function mobileStatsFor(m){const n=norm(m),g=energyStats.grupos||{};for(const [k,v] of Object.entries(g)){if(k.startsWith('DISTRIBUIDORA_MUNICIPIO|')&&norm(k.split('|').slice(2).join('|'))===n)return v}return null}
function mobileNearby(e,km=25){const lat=Number(e.latitude),lon=Number(e.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return[];return siteEvents.map(s=>{const a=Number(s.latitude),b=Number(s.longitude);if(!Number.isFinite(a)||!Number.isFinite(b))return null;const d=111*Math.hypot(a-lat,(b-lon)*Math.cos(lat*Math.PI/180));return{...s,_d:d}}).filter(Boolean).filter(s=>s._d<=km).sort((a,b)=>a._d-b._d)}
function renderMobileIntel(e){const box=document.getElementById('mobileIntel');if(!box)return;if(!e){box.innerHTML='<b>⚡ Inteligência de energia</b><span>Clique em uma falha de energia para ver histórico, recuperação e sites próximos.</span>';return}const st=mobileStatsFor(e.municipio),near=mobileNearby(e),crit=near.filter(siteIsCritical),same=energyEvents.filter(x=>norm(x.municipio)===norm(e.municipio));box.innerHTML=`<b>⚡ ${esc(e.municipio||e.regiao)}</b><span><strong>${same.length}</strong> área(s) com falha ativa no município</span><span><strong>${near.length}</strong> sites em até 25 km • <strong>${crit.length}</strong> ≤4h</span>${st?`<span>Histórico: <strong>${esc(st.amostra)}</strong> resoluções • média <strong>${Number(st.media_horas).toFixed(1)}h</strong> • mediana <strong>${Number(st.mediana_horas).toFixed(1)}h</strong> • P75 <strong>${Number(st.p75_horas).toFixed(1)}h</strong></span>`:'<span>Histórico municipal ainda sem amostra suficiente.</span>'}<span>${crit.slice(0,6).map(x=>`${esc(x.site||x.codigo||x.nome||'site')} ${x._d.toFixed(1)} km`).join(' • ')||'Nenhum site ≤4h nas redondezas.'}</span>`}
async function loadEnergyStats(){try{const r=await fetch(`${ENERGY_STATS_DATA}?t=${Date.now()}`,{cache:'no-store'});if(r.ok)energyStats=await r.json()}catch(e){console.warn('Falha estatísticas energia',e)}}
function renderMobileFocus(){const panel=document.getElementById('mobileFocusPanel');if(!panel||panel.hidden)return;const crit=siteEvents.filter(siteIsCritical).length;document.getElementById('mobileTotalSites').textContent=siteEvents.length.toLocaleString('pt-BR');document.getElementById('mobileCriticalSites').textContent=crit.toLocaleString('pt-BR');document.getElementById('mobileEnergyEvents').textContent=energyEvents.length.toLocaleString('pt-BR')}
