function focusPreventionInpe(e){preventionInpeLayer.clearLayers();if(!e?.geometry)return;const c=preventionInpeColor(e.nivel),g=L.geoJSON({type:'Feature',properties:{},geometry:e.geometry},{style:{color:c,weight:Number(e.nivel)>=2?4:2,fillColor:c,fillOpacity:Number(e.nivel)>=2?.16:.07,dashArray:Number(e.nivel)===1?'6 7':null}}).addTo(preventionInpeLayer);for(const m of (e.municipios||[]).slice(0,10)){const lat=Number(m.latitude_media),lon=Number(m.longitude_media);if(!Number.isFinite(lat)||!Number.isFinite(lon))continue;L.circleMarker([lat,lon],{radius:m.sites_ate_4h?7:4,color:c,weight:2,fillColor:c,fillOpacity:.9}).bindTooltip(`${m.municipio} • ${m.sites} sites • ${m.sites_ate_4h} ≤4h`).addTo(preventionInpeLayer)}try{map.fitBounds(g.getBounds(),{padding:[45,45],maxZoom:9})}catch(err){}}
